  created_at timestamp with time zone DEFAULT now() NOT NULL,
  primary_color character varying(7) DEFAULT '#0B132B'::character varying,
  secondary_color character varying(7) DEFAULT '#D4AF37'::character varying,
  flyer_theme text DEFAULT 'dark'::text NOT NULL,
  phone text,
  updated_at timestamp with time zone DEFAULT now(),
  slug text NOT NULL,
  crm_settings jsonb DEFAULT '{}'::jsonb NOT NULL,
  wa_credits_monthly integer,
  wa_broker_daily_cap integer,
  wa_broker_weekly_cap integer,
  lead_ref_seq integer DEFAULT 0 NOT NULL,
  deal_ref_seq integer DEFAULT 0 NOT NULL,
  code_prefix text,
  unit_code_seq integer DEFAULT 0 NOT NULL,
  plan text DEFAULT 'office'::text NOT NULL,
  paid_until timestamp with time zone,
  trial_ends_at timestamp with time zone,
  pilot boolean DEFAULT false NOT NULL,
  approval text DEFAULT 'approved'::text NOT NULL,
  signed_up_at timestamp with time zone,
  lead_rules jsonb DEFAULT '{}'::jsonb NOT NULL,
  price_reading jsonb DEFAULT '{}'::jsonb NOT NULL,
  assistant jsonb DEFAULT '{}'::jsonb NOT NULL,
  referral_code text,
  referred_by uuid,
  referral_rewarded_at timestamp with time zone,
  referral_credit_months smallint DEFAULT 0 NOT NULL,
  lead_routing jsonb DEFAULT '{}'::jsonb NOT NULL
);

